# MES version of fig_h_strat_pop.py generated by scratch make_figs_mes.py (PREREG_MESCKPT); reads the *_mes data files; writes fig_h_strat_pop_mes.pdf
"""Hypothesis figure H-b: which held-out test targets MSCA + MES lifts into the top 20, by the relation of the target to
the training history (co-occurrence neighbor or not) and by its popularity.

Hypothesis (as posed): the targets crowded out of the MSCA top 20 are mostly items that are not co-occurrence neighbors of
the history and less popular items, and MES should lift them. Data: tables/hyp_strat_pop.csv
(tables/src/collect_hyp_strat.py; MSCA and MSCA + MES best-valid checkpoints, seeds 1-5, one run per seed: P04_listana
reruns for Baby / Pantry / Scientific, Table I runs of P04_sports for Sports). Unit = one held-out test target (u, y).
  (a) gain of the top-20 hit rate (share of targets ranked <= 20, percentage points), MSCA + MES minus MSCA on the same
      seed, for targets that are co-occurrence neighbors of >= 1 training-history item of u (MSCA co-occurrence graph,
      grouping 'struct' of the CSV, the graph of the anchor term) and for the other targets. Dots = seeds, bar = mean.
  (b) the same gain by popularity quintile of the target (training degree; Q1 = least popular fifth of the targets).
      Grouped bars (2026-10-07, user request: the connected lines tangled): per quintile one bar per dataset, four tones
      of C_OURS from dark (Baby) to light (Sports), bar = mean over seeds 1-5, thin dark whisker = range over the seeds.
Usage: python -s figures/src/fig_h_strat_pop.py
"""
import csv
import statistics as st

from style import C_GREY, C_OURS, COL, TABLES, plt, save, setup

SRC = TABLES / 'src' / 'data' / 'hyp_strat_pop_mes.csv'
DATASETS = [('baby', 'Baby'), ('pantry', 'Pantry'), ('scientific', 'Scientific'), ('sports', 'Sports')]
STYLE = {'baby': ('o', '-'), 'pantry': ('s', '--'), 'scientific': ('^', ':'), 'sports': ('D', (0, (3, 1, 1, 1)))}
SEEDS = ['1', '2', '3', '4', '5']
GROUPS = [('nbr', 'Neighbor', C_OURS), ('non', 'Non-neighbor', C_GREY)]


def main():
    setup()
    rows = list(csv.DictReader(open(SRC, newline='', encoding='utf-8')))
    v = {(r['dataset'], r['arm'], r['seed'], r['grouping'], r['group']): float(r['hit20']) for r in rows}
    gain = lambda ds, gg, g: [100 * (v[(ds, 'mes', s, gg, g)] - v[(ds, 'native', s, gg, g)]) for s in SEEDS]
    fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(COL, 1.5), gridspec_kw=dict(width_ratios=[1.0, 1.0]))

    # (a) co-occurrence neighbor of the history or not
    w = 0.18
    for j, (ds, D) in enumerate(DATASETS):
        for a, (g, lab, col) in enumerate(GROUPS):
            x0 = j + (a - 0.5) * 2 * w
            y = gain(ds, 'struct', g)
            ax1.bar(x0, st.mean(y), 2 * w * 0.85, color=col, alpha=0.35, lw=0, label=lab if j == 0 else None)
            ax1.scatter([x0] * len(y), y, s=5, color=col, zorder=3, linewidths=0)
    ax1.axhline(0, color='black', lw=0.5, zorder=1)
    ax1.set_xticks(range(len(DATASETS)))
    ax1.set_xticklabels([D for _, D in DATASETS], fontsize=5.6)
    ax1.set_xlim(-0.6, len(DATASETS) - 0.4)
    ax1.set_ylim(-2, 6.5)
    ax1.set_yticks([0, 2, 4, 6])
    ax1.set_ylabel('Hit-rate gain (points)')
    ax1.set_title('(a) Co-occurrence neighbor', pad=3)
    ax1.legend(loc='upper left', frameon=False, handlelength=0.9, handletextpad=0.3, borderaxespad=0.2, labelspacing=0.2,
               ncol=2, columnspacing=0.6, fontsize=5.6)

    # (b) popularity quintile
    Q = [f'q{q}' for q in range(1, 6)]
    tones = ['#1f4e8c', '#4a78b5', '#86a9d6', '#c3d5ec']   # C_OURS dark to light, one per dataset
    bw = 0.19
    for k, (ds, D) in enumerate(DATASETS):
        xs = [i + (k - (len(DATASETS) - 1) / 2) * bw for i in range(len(Q))]
        g = [gain(ds, 'pop', q) for q in Q]
        m = [st.mean(x) for x in g]
        ax2.bar(xs, m, bw * 0.92, color=tones[k], lw=0, label=D, zorder=2)
        ax2.errorbar(xs, m, yerr=[[a - min(x) for a, x in zip(m, g)], [max(x) - a for a, x in zip(m, g)]],
                     color='#222222', ls='', elinewidth=0.5, capsize=0.8, capthick=0.5, zorder=3)
    ax2.axhline(0, color='black', lw=0.5, zorder=1)
    ax2.set_xticks(range(len(Q)))
    ax2.set_xticklabels([f'Q{q}' for q in range(1, 6)])
    ax2.set_xlabel('Popularity quintile of the target')
    ax2.set_ylim(-3, 7.5)
    ax2.set_title('(b) Popularity', pad=3)
    ax2.legend(loc='upper left', ncol=2, frameon=False, handlelength=0.9, borderaxespad=0.2, handletextpad=0.3,
               labelspacing=0.2, columnspacing=0.5, fontsize=5.4)
    for ax in (ax1, ax2):
        ax.grid(axis='y', lw=0.3, alpha=0.5)
        ax.set_axisbelow(True)
    fig.tight_layout(w_pad=0.8)
    save(fig, 'fig_h_strat_pop_mes', [SRC])


if __name__ == '__main__':
    main()
